const REPLIES = { ask: ASK, premium: PREMIUM, housing: HOUSING, food: FOOD, family: FAMILY, jobs: JOBS, daily: DAILY };

function assertReplies(counts) {
  for (const [key, n] of Object.entries(counts)) {
    if (!REPLIES[key] || REPLIES[key].length !== n) {
      throw new Error(`replies ${key} has ${REPLIES[key] ? REPLIES[key].length : 0}, expected ${n}`);
    }
  }
}

module.exports = { REPLIES, assertReplies };
